-- Dansk portion 8 del 3/3: 166 MC-spørgsmål på sværhedsskalaen 1-10.000, niveau 6596-9992.
-- Del af de 5.000 nye danskopgaver. Skrevet fra bunden til dansk folkeskole, 3.-9. klasse.
-- Genereret af tools/questions/build-danish-5000.mjs; ret i tools/questions/fixtures/danish-5000/, ikke her.
-- Kræver migration A (20261020120000_difficulty_scale_a): kolonnen questions.difficulty_level.
--
-- Niveau: hver opgave har et eksplicit difficulty_level (forfatterens skøn, ikke en måling).
-- target_grade/difficulty_band er afledt baglæns af niveauet (cellen i §4.1).
--
-- INAKTIV VED INDSÆTTELSEN: alle rækker får is_active=false og metadata.level_batch='danish8'.
-- Aktivering er en SEPARAT migration efter dokumenteret stikprøvekontrol og særskilt ejergodkendelse.
-- Må KUN anvendes via apply_migration med særskilt ejer-autorisation (D-110).

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band, difficulty_level)
SELECT
  jsonb_build_object('question', e->>'q', 'options', e->'o', 'correct', e->>'a',
                     'accepted_answers', jsonb_build_array(e->>'a'), 'review_text', e->>'r'),
  'mc', 'short',
  jsonb_build_object('concepts', jsonb_build_array(m.concept), 'cognitive_skill', m.skill,
                     'difficulty_type', m.dtype, 'misconception_type', m.mis,
                     'challenge_role', e->>'role', 'insight_type', e->>'insight',
                     'practice_variant', e->>'variant',
                     'level_batch', 'danish8', 'domain', 'danish'),
  'mc_single', (e->>'b')::int, 'auto', false, 'danish', (e->>'g')::int,
  (e->>'b')::int, (e->>'l')::int
FROM jsonb_array_elements($$[
{"l":6596,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Mormor stiller 'kaution' for Yusufs lån. Hvad betyder det?","o":["hun låner selv penge af Yusuf","hun forbyder Yusuf at låne penge","hun lover at betale, hvis han ikke kan","hun rådgiver Yusuf om renter i banken"],"a":"hun lover at betale, hvis han ikke kan","r":"Den, der kautionerer, står inde for gælden. Banken kan kræve pengene hos kautionisten, hvis låntageren ikke betaler."},
{"l":6618,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Kommunen bevilgede penge til en ny hal.' Hvad gjorde kommunen?","o":["bad om at få pengene","opkrævede pengene hos borgerne","brugte pengene på noget andet","besluttede at give pengene"],"a":"besluttede at give pengene","r":"At bevilge er at give tilladelse til, at der bliver brugt penge på noget. Ordet bruges især om det offentlige og fonde."},
{"l":6640,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning bruger tankestreger rigtigt om en indskudt bemærkning?","o":["Min moster – hun bor i Bergen – kommer på besøg.","Min moster – hun bor i Bergen kommer – på besøg.","Min – moster hun bor i Bergen – kommer på besøg.","Min moster hun – bor i Bergen – kommer på besøg."],"a":"Min moster – hun bor i Bergen – kommer på besøg.","r":"Tankestregerne står på hver sin side af den indskudte bemærkning 'hun bor i Bergen'."},
{"l":6660,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket ord skal have stort: 'Vi var på besøg i folketinget på Christiansborg i maj.'?","o":["besøg","folketinget","maj","på"],"a":"folketinget","r":"Folketinget er navnet på en bestemt institution og får stort."},
{"l":6680,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Efter hvilket ord skal der komma: 'Om Malthe når toget ved ingen endnu.'?","o":["når","ved","toget","ingen"],"a":"toget","r":"'Om Malthe når toget' er en ledsætning, der står først, så der skal komma efter den."},
{"l":6700,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'En kendt skuespiller fortæller på tv, at hendes nye madras har fjernet hendes rygsmerter. Så må det jo være rigtigt, skriver bloggeren.' Hvad er svagheden i bloggerens slutning?","o":["At madrasser ikke kan købes af almindelige mennesker","At rygsmerter ikke er et emne, man taler om på tv","At bloggeren ikke selv har set udsendelsen i tv","At hun er skuespiller og ikke ved mere om ryg end andre"],"a":"At hun er skuespiller og ikke ved mere om ryg end andre","r":"At hun er kendt, betyder ikke, at hun ved noget om ryg og madrasser. Måske blev ryggen bedre af en helt anden grund."},
{"l":6719,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning om planter har en s-form, der ikke er passiv?","o":["Mine planter trives i vinduet.","Planterne vandes hver dag.","De visne blade klippes af.","Potterne sælges i haven."],"a":"Mine planter trives i vinduet.","r":"'Trives' findes kun med -s og har ingen aktiv udgave. Det er ikke passiv, for ingen gør noget ved planterne."},
{"l":6738,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Guld er et 'grundstof'. Hvad betyder det?","o":["det er en blanding af flere metaller","det består kun af én slags atomer","det findes kun dybt nede i jorden","det kan kun fremstilles på en fabrik"],"a":"det består kun af én slags atomer","r":"Alle grundstoffer står i det periodiske system. Et grundstof kan ikke deles op i andre stoffer ved kemiske reaktioner."},
{"l":6760,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken af forkortelserne skal have punktum efter sig, når den står i en almindelig sætning?","o":["km","kg","mio","cm"],"a":"mio","r":"'Mio.' er en forkortelse af 'million'. Km, kg og cm er måleenheder og skrives uden punktum."},
{"l":6780,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken skrivemåde er rigtig: 'Bygningen, hvor De Forenede Nationer holder til i New York, kaldes ___.'?","o":["FN bygningen","FN:bygningen","FN'bygningen","FN-bygningen"],"a":"FN-bygningen","r":"En forkortelse, der bliver sat sammen med et ord, får bindestreg."},
{"l":6799,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg stavemåden: 'Læg brevet i en ___, og sæt frimærke på.'","o":["kuvert","kuværd","kouvert","kuverdt"],"a":"kuvert","r":"Ordet kommer fra fransk, men skrives med k og u på dansk, og det ender på t."},
{"l":6812,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Klassen deltog i en ___ i rundbold mod de andre skoler.'","o":["tunering","turnering","turnerring","tournering"],"a":"turnering","r":"Ordet har r foran n'et og kun ét r i den sidste del."},
{"l":6829,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning er en nægtet bydeform?","o":["Du glemte ikke din madpakke.","Har du glemt din madpakke?","Glem ikke din madpakke.","Din madpakke er ikke glemt."],"a":"Glem ikke din madpakke.","r":"'Glem' er bydeform, og 'ikke' gør opfordringen nægtende. De andre sætninger fortæller eller spørger."},
{"l":6851,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilket fremmedord er stavet rigtigt: 'Filmen begynder ___ klokken otte, så kom til tiden.'","o":["præsis","precis","præciis","præcis"],"a":"præcis","r":"Ordet skrives med æ, og s-lyden i midten er et c."},
{"l":6876,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Læreren påtalte elevens sprogbrug.' Hvad gjorde læreren?","o":["sagde, at sproget ikke var i orden","roste sproget foran klassen","rettede stavefejlene i teksten","oversatte teksten til et andet sprog"],"a":"sagde, at sproget ikke var i orden","r":"At påtale noget er at kritisere det og gøre opmærksom på, at det ikke er acceptabelt."},
{"l":6893,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Kildekritik begynder med tre spørgsmål: Hvem siger det? Hvorfor siger de det? Hvordan ved de det? På sin hjemmeside skriver en bager, at han laver byens bedste brød.' Hvilket spørgsmål afslører hurtigst, at man skal være forsigtig?","o":["Hvordan laves brødet?","Hvorfor siger de det?","Hvad koster brødet?","Hvor ligger bageren?"],"a":"Hvorfor siger de det?","r":"Bageren vil gerne sælge brød. Derfor er det reklame, når han selv skriver, at hans brød er det bedste."},
{"l":6912,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilket mønster følger mange eventyr, når helten drager af sted?","o":["ude-hjem-ude","nutid-fremtid-nutid","hjem-ude-hjem","slutning-midte-start"],"a":"hjem-ude-hjem","r":"Helten forlader hjemmet, består prøver ude i verden og vender hjem forandret eller belønnet."},
{"l":6929,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilken stavemåde er korrekt? 'Buschaufføren bad en ___ om at sætte sig ned.'","o":["pasager","passasjer","passagerr","passager"],"a":"passager","r":"Ordet kommer fra fransk og har dobbelt-s og g, selvom det lyder som sj."},
{"l":6955,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg stavemåden: 'Vi har en ___ prøve i gloser, så vi skal øve os hver uge.'","o":["ugentlig","ugenlig","ugendlig","ugentli"],"a":"ugentlig","r":"Ordet har et t foran -lig, ligesom 'egentlig'. Husk det, selvom det kan lyde som d."},
{"l":6973,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Der blev iværksat foranstaltninger mod oversvømmelser.' Hvilket ord kan stå i stedet for 'foranstaltninger'?","o":["fester","tiltag","regnskaber","klager"],"a":"tiltag","r":"En foranstaltning er noget, man gør for at opnå eller undgå noget. Ordet hører hjemme i formelt sprog."},
{"l":6994,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Ali var ___ i en pige fra parallelklassen.'","o":["forælsket","forelsked","forelsket","forelskt"],"a":"forelsket","r":"Ordet kommer af 'elske' og har derfor e. Det ender på -et."},
{"l":7011,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hun svarede 'diplomatisk' på kritikken. Hvordan svarede hun?","o":["hun råbte og blev meget vred over det","hun løj om, hvad der virkelig var sket","hun sagde ikke et eneste ord til nogen","hun valgte sine ord uden at støde nogen"],"a":"hun valgte sine ord uden at støde nogen","r":"Ordet kommer af 'diplomat'. En diplomat skal kunne håndtere svære sager mellem lande med takt og omtanke."},
{"l":7033,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad står der rigtigt? 'Har du ___ dit vand, eller skal jeg tage glasset?'","o":["drukket","drikket","druket","drukke"],"a":"drukket","r":"Tillægsformen af 'drikke' skifter i til u og beholder dobbelt-k."},
{"l":7056,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilken genre er en personlig, undersøgende tekst, hvor forfatteren tænker højt om et emne uden at ville give et endeligt svar?","o":["reportage","essay","fabel","leder"],"a":"essay","r":"Ordet essay kommer af fransk 'essai', forsøg. Skribenten undersøger et emne personligt og åbent."},
{"l":7072,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg rigtigt: 'Det passer mig ___, at vi mødes klokken fire.'","o":["udmerket","udmærked","udmærket","udmærkt"],"a":"udmærket","r":"Ordet kommer af 'mærke' og skrives med æ. Det ender på -et."},
{"l":7098,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find ordet: 'Han trådte ___ på bolden for at stoppe spillet.'","o":["bevist","bevisst","bevidt","bevidst"],"a":"bevidst","r":"Her betyder ordet 'med vilje'. Det hænger sammen med 'vide' og har d. 'Bevist' kommer af 'bevise'."},
{"l":7116,"g":7,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det at 'kaste handsken' til nogen?","o":["at udfordre personen","at give personen en gave","at bede personen om tilgivelse","at sige farvel til personen"],"a":"at udfordre personen","r":"I gamle dage kastede en ridder handsken for modstanderens fødder, når han udfordrede til tvekamp."},
{"l":7145,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det at 'evaluere' et undervisningsforløb?","o":["at afslutte det før tid","at vurdere, hvordan det er gået","at gentage det fra begyndelsen","at forklare det for nye elever"],"a":"at vurdere, hvordan det er gået","r":"Når man evaluerer, ser man tilbage og vurderer, hvad der virkede, og hvad der ikke gjorde. Det handler altså om bedømmelse, ikke om at stoppe eller starte forfra."},
{"l":7160,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Omtrent hvornår begyndte romantikken i dansk litteratur?","o":["omkring år 1500","omkring år 1870","omkring år 1800","omkring år 1960"],"a":"omkring år 1800","r":"Romantikken kom til Danmark omkring år 1800. 1870 er det moderne gennembrud."},
{"l":7183,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Efter løbeturen var hans ___ tung og hurtig.'","o":["vejrtrækkning","vejtrækning","vejrtrækin","vejrtrækning"],"a":"vejrtrækning","r":"Ordet består af 'vejr' og 'trækning'. R'et i 'vejr' skal med, og der er kun ét k."},
{"l":7202,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilket værk er skrevet af Steen Steensen Blicher?","o":["Hosekræmmeren","Den onde lykke","Ved Vejen","Babettes Gæstebud"],"a":"Hosekræmmeren","r":"'Hosekræmmeren' er en af Blichers mest kendte noveller og foregår på den jyske hede."},
{"l":7223,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning har både et indirekte og et direkte objekt?","o":["Mor købte en ny trøje.","Mor gav Karl en ny trøje.","Mor gik til butikken.","Mor er glad for trøjen."],"a":"Mor gav Karl en ny trøje.","r":"'Karl' er den, der får noget, og 'en ny trøje' er det, der gives. Verber som 'give' kan have begge slags objekter."},
{"l":7242,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilken slags bog er en 'autobiografi'?","o":["en bog, hvor en forsker fortæller om kendte biler","en bog, hvor mange forfattere samler deres digte","en bog, hvor forfatteren fortæller om sit eget liv","en bog, hvor en journalist skriver om en kendt person"],"a":"en bog, hvor forfatteren fortæller om sit eget liv","r":"'Auto' betyder selv, 'bio' betyder liv, og 'grafi' betyder skrift. Skriver en anden om personens liv, er det kun en biografi."},
{"l":7265,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Et forslag 'falder mellem to stole'. Hvad sker der med det?","o":["det bliver vedtaget af begge parter","det bliver udsat til efter sommerferien","det bliver delt op i to mindre forslag","det hører ikke rigtigt til nogen af siderne"],"a":"det hører ikke rigtigt til nogen af siderne","r":"Noget, der falder mellem to stole, passer ikke ind nogen af de to steder, hvor det kunne høre til. Derfor bliver det let overset."},
{"l":7286,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilket emne er typisk for en roman fra det moderne gennembrud?","o":["Kvinders ulige vilkår i ægteskabet","Nordens guder og fortidens helte","Sprogeksperimenter uden nogen handling","Længsel efter en guddommelig natur"],"a":"Kvinders ulige vilkår i ægteskabet","r":"Forfatterne ville debattere samfundets problemer, og ægteskab og kvinders vilkår var et hovedemne."},
{"l":7302,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Eleverne var 'solidariske' med en klassekammerat. Hvad gjorde de?","o":["de undgik hende og talte om hende bagefter","de støttede hende og stod sammen med hende","de konkurrerede med hende om den bedste plads","de lånte hendes bøger og glemte at give dem tilbage"],"a":"de støttede hende og stod sammen med hende","r":"At være solidarisk er at stå sammen med nogen og bakke dem op, også når det koster en selv noget."},
{"l":7325,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad gør man, når man 'perspektiverer' en novelle?","o":["man gengiver handlingen kort med sine egne ord","man finder alle personerne, som optræder i teksten","man sætter den i forhold til noget uden for teksten","man retter stavefejlene, før den bliver afleveret"],"a":"man sætter den i forhold til noget uden for teksten","r":"Når man perspektiverer, sammenligner man teksten med for eksempel en anden tekst, en periode eller noget i samfundet. Gengivelse af handlingen er et referat."},
{"l":7344,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket stedord skal stå: 'Gaven er til Nanna og ___.'?","o":["han","hans","sin","ham"],"a":"ham","r":"Efter forholdsordet 'til' står stedordet i afhængighedsform: 'til ham'. Tænk, hvad der ville stå uden 'Nanna og'."},
{"l":7366,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Genstandsleddet 'Den film' skal stå først. Hvilken ordstilling er rigtig?","o":["Den film har jeg set to gange.","Den film jeg har set to gange.","Den film set har jeg to gange.","Den film to gange jeg har set."],"a":"Den film har jeg set to gange.","r":"Uanset hvilket led der står først i en hovedsætning, skal det bøjede verbum på andenpladsen. Derfor står 'har' lige efter 'Den film'."},
{"l":7385,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Vi var de sidste, der forlod huset. Far låste, selv om der ikke var noget tilbage at passe på. Så stod han med nøglen i hånden, som om han ventede på, at nogen skulle tage den fra ham.' Hvad vil uddraget vise?","o":["At far er bange for, at nogen vil bryde ind","At det er svært for far at give slip på huset","At far har glemt, hvem nøglen skal gives til","At far er utålmodig efter at komme videre"],"a":"At det er svært for far at give slip på huset","r":"Der er ikke noget at passe på, så far behøver ikke at låse. Han står bare med nøglen og venter, fordi han ikke har lyst til at sige farvel."},
{"l":7400,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Sagen er ikke, at unge ikke kan koncentrere sig. De kan sidde i fire timer med et spil og i fire minutter med en lærebog.' Hvad er skribentens forklaring?","o":["Unge har mistet evnen til at koncentrere sig","Spil er vigtigere for unge end lærebøger","Unge kan koncentrere sig om det, der interesserer dem","Lærebøger bør laves om til computerspil"],"a":"Unge kan koncentrere sig om det, der interesserer dem","r":"Skribenten siger, at unge godt kan koncentrere sig. Fire timer med spillet og fire minutter med bogen viser, at det kommer an på, om de er interesserede."},
{"l":7421,"g":8,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find det rigtige ord: 'Gymnastik er en ___ aktivitet, der styrker kroppen.'","o":["fysik","fysist","fyssisk","fysisk"],"a":"fysisk","r":"Tillægsordet ender på -isk. 'Fysik' er navnet på et fag og passer ikke foran 'aktivitet'."},
{"l":7442,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Stort tillykke til bestyrelsen i håndboldklubben. Efter tre møder og en rapport på 40 sider har den fundet ud af, at omklædningsrummet lugter. Rapporten anbefaler nu endnu et møde.' Hvad er skribentens budskab?","o":["At der bliver talt meget om noget, som ingen gør noget ved","At bestyrelsen har gjort et grundigt arbejde med et overset problem","At omklædningsrummet lugter værre, end bestyrelsen er klar over","At rapporten burde have været kortere og lettere at læse"],"a":"At der bliver talt meget om noget, som ingen gør noget ved","r":"Lykønskningen er ironisk: Alle ved, at rummet lugter, og resultatet er bare endnu et møde. Tager man 'tillykke' bogstaveligt, overser man, at intet bliver løst."},
{"l":7461,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilke ord dækker bedst 'kompleks', når ordet bruges om en sag?","o":["stor og tung","sammensat og indviklet","grundig og omhyggelig","ny og ukendt"],"a":"sammensat og indviklet","r":"En kompleks sag består af mange dele, der hænger sammen, så den er svær at overskue. Det er noget andet end 'stor'."},
{"l":7483,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Forskere fandt en 'signifikant' forskel mellem to grupper. Hvad betyder det?","o":["at forskellen kun kan ses på papiret","at forskellen er opfundet af forskerne","at forskellen næppe skyldes en tilfældighed","at forskellen er mindre end forventet"],"a":"at forskellen næppe skyldes en tilfældighed","r":"I statistik betyder signifikant, at et resultat er så tydeligt, at det næppe er opstået ved et tilfælde. Ordet kan også bare betyde 'betydningsfuld'."},
{"l":7500,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Journalisten skriver: Forfatteren vil ikke kommentere sagen. I forfatterens svarmail stod der: Jeg er på ferie og svarer på mandag.' Hvad har journalisten gjort?","o":["Skrevet præcis det, forfatteren svarede","Ventet til mandag med at bringe artiklen","Bedt forfatteren om at svare hurtigere på mailen","Fået det til at lyde, som om forfatteren siger nej"],"a":"Fået det til at lyde, som om forfatteren siger nej","r":"Forfatteren skrev, at svaret kommer på mandag. Det er ikke det samme som at nægte at svare."},
{"l":7519,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvordan staves ordet? 'Blæksprutten er et ___ dyr, der kan løse opgaver.'","o":["intelligent","inteligent","intellegent","intelligænt"],"a":"intelligent","r":"Ordet har dobbelt-l, og der står i foran g'et."},
{"l":7536,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Klassen vil 'eliminere' fejlkilderne i forsøget. Hvad vil de gøre med dem?","o":["tælle dem op","fjerne dem helt","skrive dem ned","vise dem frem"],"a":"fjerne dem helt","r":"At eliminere er at fjerne noget fuldstændigt. Ordet kommer af latin og betyder egentlig 'at sætte uden for døren'."},
{"l":7558,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilken komedie af Ludvig Holberg handler om en bonde, der vågner op i baronens seng?","o":["Erasmus Montanus","Den Stundesløse","Jeppe på Bjerget","Den Politiske Kandestøber"],"a":"Jeppe på Bjerget","r":"I 'Jeppe på Bjerget' tror bonden Jeppe, at han er kommet i himlen, da han vågner i baronens seng."},
{"l":7581,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det at 'gendrive' en påstand?","o":["at gentage den med egne ord","at støtte den med nye eksempler","at trække den tilbage igen","at vise, at den er forkert"],"a":"at vise, at den er forkert","r":"Når man gendriver, modbeviser man en andens påstand med argumenter. 'Gen-' betyder her 'imod'."},
{"l":7600,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'I sit nytårsbrev skriver rektor, at året har budt på udfordringer, som vi sammen har vendt til læring. Lærerne husker året som det, hvor halvdelen af dem sagde op.' Hvad er forholdet mellem de to beskrivelser?","o":["Rektor får et hårdt år til at lyde pænt","Rektor og lærerne beskriver to helt forskellige skoleår","Rektor og lærerne husker året på samme måde","Lærerne har misforstået, hvad rektor skrev i sit brev"],"a":"Rektor får et hårdt år til at lyde pænt","r":"'Udfordringer' og 'læring' er pæne ord. Lærerne husker, at halvdelen af dem sagde op. Rektor nævner det ikke."},
{"l":7619,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning om dans er en upersonlig passiv?","o":["Hun danser hele aftenen.","Der danses hele aftenen.","Pigerne danser hele aftenen.","Dansen varer hele aftenen."],"a":"Der danses hele aftenen.","r":"I en upersonlig passiv er 'der' formelt grundled, og sætningen nævner slet ikke, hvem der gør noget."},
{"l":7641,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning om reglerne har s-passiv og ikke passiv med 'blive'?","o":["Reglerne blev fulgt.","Reglerne er blevet fulgt.","Reglerne skal følges.","Reglerne bliver fulgt."],"a":"Reglerne skal følges.","r":"'Følges' er s-form. Efter modalverber som 'skal' bruger man ofte s-passiv, mens de andre sætninger bruger 'blive' og kort tillægsform."},
{"l":7663,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken form passer: 'I går ___ jeg, at filmen var god, men nu er jeg i tvivl.'?","o":["synes","synte","synets","syntes"],"a":"syntes","r":"'I går' kræver datid, og datid af 'synes' hedder 'syntes'. Nutid staves 'synes'."},
{"l":7685,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning indeholder både en lang og en kort tillægsform?","o":["Den grædende dreng har slået knæet.","Den grædende dreng vil gerne hjem.","Drengen har slået knæet i skolen.","Drengen græder og vil gerne hjem."],"a":"Den grædende dreng har slået knæet.","r":"'Grædende' er lang tillægsform, og 'slået' er kort tillægsform efter 'har'. De andre sætninger har højst én af delene."},
{"l":7701,"g":8,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find det rigtige ord: 'Butikken sælger ___ sko, men der er også nogle få tasker.'","o":["fordrinsvis","fortrinsvis","fortrinvis","fortrinsvist"],"a":"fortrinsvis","r":"Ordet består af 'fortrin' og -vis med et fuge-s imellem. Der er ikke noget t til sidst."},
{"l":7722,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Efter hvilket ord skal der komma: 'Det du siger kan godt passe.'?","o":["du","kan","siger","godt"],"a":"siger","r":"'du siger' er en ledsætning uden indledende ord, og den skal stadig afsluttes med komma."},
{"l":7744,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvad ændrer kommaet i 'Vi ringer, far.' i forhold til 'Vi ringer far.'?","o":["Far bliver genstandsled i sætningen","Sætningen bliver til et spørgsmål","Sætningen får en ekstra ledsætning","Far bliver tiltalt og ikke ringet til"],"a":"Far bliver tiltalt og ikke ringet til","r":"Med komma er 'far' en tiltale: Man fortæller ham noget. Uden komma er far den, man ringer til."},
{"l":7762,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'To elever fik en advarsel, efter at de havde filmet en lærer. Elevrådet mener, at straffen er for hård. Skolen henviser til ordensreglerne, som elevrådet selv var med til at skrive.' Hvorfor nævner skolen, hvem der skrev reglerne?","o":["For at elevrådet ikke skal kunne klage over reglerne","For at takke elevrådet for det gode arbejde med reglerne","For at få elevrådet til at skrive nye regler","For at vise, at lærerne ikke kender reglerne"],"a":"For at elevrådet ikke skal kunne klage over reglerne","r":"Skolen siger i virkeligheden: I har selv været med til at lave reglerne, så I kan ikke klage over dem nu."},
{"l":7784,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Fra 1. august overgår vi til et nyt og mere fleksibelt vagtsystem, hvor medarbejderne i højere grad selv får ansvar for at finde afløsere.' Hvad sker der reelt for medarbejderne?","o":["De får færre vagter og mere fri end i dag","De får en opgave, som firmaet tidligere selv løste","De får løn for at finde sig en ny afløser","De får lov til selv at bestemme deres vagtplan"],"a":"De får en opgave, som firmaet tidligere selv løste","r":"'Fleksibelt' og 'ansvar' lyder som goder, men i praksis er det ekstra arbejde. Teksten pakker en byrde ind i positive ord."},
{"l":7800,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Kongen forbød ordet sult. Året efter meldte alle landets embedsmænd, at ingen længere sultede.' Hvad går fortællingen ud på?","o":["Embedsmændene har reddet landet ud af hungersnøden","Kongen har opdaget en ny metode til at dyrke korn","Man kan ændre sproget uden at ændre virkeligheden","Ordet sult har altid været forbudt i det pågældende land"],"a":"Man kan ændre sproget uden at ændre virkeligheden","r":"Når et ord forbydes, kan ingen rapportere problemet, men det forsvinder ikke. Teksten er satire over magt og sprog."},
{"l":7819,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Det første, jeg lagde mærke til, var, at hun havde fjernet billedet af os. Det andet var, at væggen var lysere dér, hvor det havde hængt.' Hvad kan den lyse plet stå for?","o":["At væggen trænger til en ny omgang maling","At fortælleren er glad for den nye indretning","At hun gerne vil have billedet op at hænge igen","At det, de havde sammen, ikke bare kan fjernes"],"a":"At det, de havde sammen, ikke bare kan fjernes","r":"Billedet er væk, men pletten på væggen viser, at det har hængt der. Sådan er det også med de to: Det, de har haft, sidder stadig tilbage."},
{"l":7841,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilken form passer? 'Forskere, der ___ havets dyr, tager ofte ud på lange togter.'","o":["undersøger","undersøge","undersører","undersøgere"],"a":"undersøger","r":"Grundleddet er 'der', og udsagnsordet står i nutid, så det får -r: der undersøger."},
{"l":7859,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Skolen skal 'implementere' en ny læseplan. Hvad skal skolen gøre?","o":["stemme om den","føre den ud i praksis","skrive den om","oversætte den"],"a":"føre den ud i praksis","r":"At implementere er at sætte noget i værk og få det til at virke i hverdagen. Ordet bruges meget i offentlige og tekniske tekster."},
{"l":7883,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find stavemåden: 'Hun vil gerne gå på et ___ i nabobyen efter 9. klasse.'","o":["gymnasiom","gynmasium","gymnasium","gymnassium"],"a":"gymnasium","r":"Ordet kommer fra græsk og skrives med y, mn og endelsen -ium."},
{"l":7904,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I en argumentation er der ofte en uudtalt antagelse, som får belægget til at støtte påstanden. Hvad kaldes den?","o":["styrkemarkør","gendrivelse","konklusion","hjemmel"],"a":"hjemmel","r":"Hjemlen er den fælles opfattelse, der forbinder belæg og påstand. Hvis modtageren ikke deler den, virker argumentet ikke."},
{"l":7925,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvordan staves ordet? 'Hunden blev ___ og begyndte at knurre.'","o":["aggressiv","agressiv","aggresiv","agresiv"],"a":"aggressiv","r":"Ordet har både dobbelt-g og dobbelt-s."},
{"l":7942,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"På bagerens skilt står der: 'Hos os er der altid noget i gære.' Hvilket virkemiddel bruger skiltet?","o":["allitteration","ordspil","personifikation","sammenligning"],"a":"ordspil","r":"'I gære' betyder både, at der sker noget, og passer til bagerens gær. Den dobbelte betydning er et ordspil."},
{"l":7967,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Skolen bør tilbyde morgenmad, fordi sultne elever ikke kan koncentrere sig i timerne.' Hvad tager skribenten for givet uden at sige det?","o":["At alle elever bliver sultne længe inden klokken otte","At skolen sparer penge, hvis der serveres morgenmad","At det er skolens opgave at sørge for, at eleverne kan lære","At eleverne foretrækker skolens mad frem for hjemmets"],"a":"At det er skolens opgave at sørge for, at eleverne kan lære","r":"At sultne elever ikke kan koncentrere sig, siger ikke, at skolen skal give mad. Det passer kun, hvis man mener, at det er skolens opgave."},
{"l":7986,"g":8,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Sætningen betyder 'Hvis du ikke kommer'. Efter hvilket ord skal der komma: 'Kommer du ikke i morgen ringer jeg til dig.'?","o":["ikke","ringer","dig","morgen"],"a":"morgen","r":"Første del er en betingelse uden 'hvis' og fungerer som ledsætning. Den afsluttes med komma."},
{"l":8004,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken modus står 'leve' i: 'Længe leve brudeparret!'?","o":["konjunktiv","imperativ","indikativ","infinitiv"],"a":"konjunktiv","r":"Konjunktiv er ønskeformen. Den bruges i dag næsten kun i faste udtryk og ser ud som navneformen."},
{"l":8024,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Vi søger en lærer, der trives med stor frihed, kan arbejde selvstændigt og ikke har brug for tæt opfølgning. Vi er et lille team, hvor alle har travlt.' Hvad antyder jobopslaget mellem linjerne?","o":["At den nye lærer får høj løn og meget ferie","At den nye lærer ikke kan regne med megen støtte","At skolen har for mange lærere i forvejen","At den nye lærer skal lede de andre i teamet"],"a":"At den nye lærer ikke kan regne med megen støtte","r":"Ordene 'frihed' og 'selvstændigt' lyder positive, men sammen med 'alle har travlt' peger de på, at man må klare sig selv."},
{"l":8046,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Asta forlader gården for at finde den sidste snefugl. Hun krydser fjeldet, narres af en talende ræv og er lige ved at fryse fast på søen. Da hun kommer hjem uden fuglen, ser hun for første gang, hvor mange fugle der bor i hendes egen have.' Historien følger mønstret hjem-ude-hjem. Hvad viser det, at Asta ender samme sted, som hun startede?","o":["Hun burde være blevet hjemme på gården fra starten","Hun er præcis den samme som før rejsen","Hun ser sit hjem på en ny måde efter rejsen","Hun vil snart af sted igen efter fuglen"],"a":"Hun ser sit hjem på en ny måde efter rejsen","r":"Asta kommer hjem til det samme sted, men nu ser hun fuglene i sin egen have. Hun fandt ikke snefuglen, men rejsen var ikke forgæves."},
{"l":8065,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Sæt ind: 'Holdet lagde en ___ før kampen.'","o":["stratægi","stratigi","strattegi","strategi"],"a":"strategi","r":"Ordet kommer fra græsk, skrives med ét t i midten og e foran g'et."},
{"l":8088,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvem skrev omkring år 1200 Danmarkshistorien 'Gesta Danorum' på latin?","o":["Saxo","Snorre Sturlason","Ludvig Holberg","Steen Steensen Blicher"],"a":"Saxo","r":"Saxo skrev 'Gesta Danorum' på latin. Værket rummer både historie og sagn, f.eks. om Amled."},
{"l":8104,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Man bør nok overveje, om det måske kunne være en idé at se nærmere på sagen på et tidspunkt.' Hvordan virker sætningen?","o":["Den lyder som et klart krav om at handle med det samme","Den lyder, som om afsenderen ikke vil love noget","Den lyder, som om afsenderen er vred over sagen","Den giver en præcis dato for, hvornår der skal ske noget"],"a":"Den lyder, som om afsenderen ikke vil love noget","r":"Med 'nok', 'måske', 'kunne' og 'på et tidspunkt' bliver det meget forsigtigt. Der står ikke, at nogen vil gøre noget."},
{"l":8125,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord er en nominalisering af 'forbedre'?","o":["forbedret","forbedrende","forbedring","forbedres"],"a":"forbedring","r":"En nominalisering gør et verbum til et navneord. De andre er former af selve verbet."},
{"l":8147,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad betyder 'bedes' i: 'Eleverne bedes møde klokken otte.'?","o":["at eleverne selv beder om det","at eleverne beder hinanden om det","at eleverne helt selv kan vælge det","at eleverne bliver bedt om det"],"a":"at eleverne bliver bedt om det","r":"'Bedes' er passiv af 'bede'. Det er en formel måde at opfordre på uden at nævne, hvem der opfordrer."},
{"l":8172,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Der var engang en prinsesse, der var træt af prinser, så hun åbnede et cykelværksted og sagde nej tak til det halve kongerige.' Hvad gør teksten med eventyrgenren?","o":["Den laver sjov med, hvordan et eventyr plejer at gå","Den følger helt nøje, hvordan et eventyr plejer at gå","Den fortæller eventyret om som en nyhed fra avisen","Den gengiver et gammelt folkeeventyr ord for ord"],"a":"Den laver sjov med, hvordan et eventyr plejer at gå","r":"Prinsessen siger nej tak til både prinser og kongerige, altså det modsatte af det, man venter i et eventyr. Den slags leg med en kendt genre kaldes parodi."},
{"l":8191,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvordan staves ordet? 'Skolens store ___ i idrætshallen samlede flere hundrede gæster.'","o":["arangement","arrangement","arrangemang","arrangemant"],"a":"arrangement","r":"Ordet kommer fra fransk og har dobbelt-r. Selvom det lyder som -ang, ender det på -ement."},
{"l":8213,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket stedord skal stå: 'Når man er træt, gør det ___ godt at sove.'?","o":["man","sig","en","ens"],"a":"en","r":"'Man' kan kun være grundled. Som hensynsled eller genstandsled hedder det 'en'."},
{"l":8233,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er rigtigt? 'De to gav begge lidt og indgik et ___.'","o":["kompromiss","kompremis","komprimis","kompromis"],"a":"kompromis","r":"Ordet ender med ét s i ental. Først i flertal 'kompromisser' bliver der dobbelt-s."},
{"l":8252,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Vi vil have cykelstier. Vi vil have cykelstier, før nogen kommer til skade. Vi vil have cykelstier nu.' Hvad gør gentagelsen?","o":["Den gør kravet stærkere, så man ikke kan overhøre det","Den viser, at skribenten har glemt, hvad der stod","Den skal få læseren til at slappe af og smile","Den gør kravet mere usikkert og mere forsigtigt"],"a":"Den gør kravet stærkere, så man ikke kan overhøre det","r":"Den samme sætning kommer igen og igen og bliver stærkere, indtil den ender med 'nu'. Det bruger man tit i taler."},
{"l":8273,"g":8,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad gør den, der 'kryber til korset'?","o":["beder om hjælp i kirken til sine problemer","indrømmer sin fejl og giver ydmygt efter","gemmer sig for at undgå en ubehagelig samtale","søger trøst hos sine nærmeste venner"],"a":"indrømmer sin fejl og giver ydmygt efter","r":"Den, der kryber til korset, må opgive sin stolte holdning og erkende, at modparten havde ret."},
{"l":8295,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er en 'eklatant' fejl?","o":["en fejl, der er svær at finde","en fejl, der er let at rette","en fejl, der er helt åbenlys","en fejl, der er uden betydning"],"a":"en fejl, der er helt åbenlys","r":"Eklatant betyder iøjnefaldende. En eklatant fejl er så tydelig, at ingen kan overse den."},
{"l":8318,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilken slags bog er Karen Blixens 'Den afrikanske Farm' fra 1937?","o":["En samling digte om den danske natur","En krimi, der foregår i en storby","En roman om en dansk præstefamilie","En skildring af hendes år i Afrika"],"a":"En skildring af hendes år i Afrika","r":"Bogen bygger på hendes egne oplevelser på kaffefarmen i det nuværende Kenya."},
{"l":8340,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er forskellen mellem en grov og en 'subtil' pointe?","o":["den subtile pointe er fin og svær at opfange","den subtile pointe er hård og let at se","den subtile pointe er lang og kedelig at høre","den subtile pointe er ny og usikker at bruge"],"a":"den subtile pointe er fin og svær at opfange","r":"Subtil betyder fin og hårfin. Det subtile opdager man kun, når man ser godt efter, modsat det grove og oplagte."},
{"l":8360,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilken forfatter skrev 'Pelle Erobreren', der følger en svensk dreng og hans far på Bornholm?","o":["Jeppe Aakjær","Martin Andersen Nexø","Hans Kirk","Johan Skjoldborg"],"a":"Martin Andersen Nexø","r":"Martin Andersen Nexø var selv vokset op på Bornholm. Romanen skildrer arbejdernes kår."},
{"l":8385,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Udtrykket 'en larmende stilhed' forbinder to modsætninger. Hvad kaldes det?","o":["en eufemisme","en pleonasme","et oxymoron","et akronym"],"a":"et oxymoron","r":"Et oxymoron sætter to modsatte ord sammen for at skabe en særlig virkning. Ordet kommer af det græske for 'skarp' og 'dum'."},
{"l":8404,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning er rigtig, når en replik følges af to hovedsætninger?","o":["»Løb!«, råbte træneren og, alle satte i gang.","»Løb«! råbte træneren, og alle satte i gang.","»Løb!« råbte, træneren og alle satte i gang.","»Løb!« råbte træneren, og alle satte i gang."],"a":"»Løb!« råbte træneren, og alle satte i gang.","r":"Udråbstegnet står inden for anførselstegnene, og kommaet står foran 'og', fordi 'alle' er nyt grundled."},
{"l":8429,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Hun havde ondt, når hun sank, og lægen sagde, at det var ___.'","o":["halsbetændelse","halsebetændelse","halsbetendelse","hals betændelse"],"a":"halsbetændelse","r":"Sammensatte ord skrives i ét. Første led er 'hals' uden ekstra e, og 'betændelse' har æ."},
{"l":8446,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Bageren på torvet havde i årevis tre slags rugbrød: et billigt, et mellemdyrt og et dyrt. Sidste forår fjernede han det dyre, fordi det solgte dårligst. To måneder senere var salget af det mellemste faldet, mens det billige solgte mere end nogensinde. Bageren forstod det ikke, for han havde hverken ændret pris eller opskrift på de to andre.' Hvad er den bedste forklaring på, at salget ændrede sig?","o":["Bageren havde hævet prisen på det mellemste brød i løbet af foråret","Det dyre brød havde fået det mellemste til at virke rimeligt i pris","Kunderne fik mere for pengene, fordi det billige brød var blevet større","Det mellemste brød smagte dårligere, efter at det dyre var forsvundet"],"a":"Det dyre brød havde fået det mellemste til at virke rimeligt i pris","r":"Uden det dyre brød blev det mellemste det dyreste på hylden, og så valgte flere det billige. Brødene var de samme, men det, kunderne sammenlignede med, var ændret."},
{"l":8470,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken funktion har semikolonet i 'Hun løb; han gik.'?","o":["Det viser, at der kommer en opremsning af ting","Det varsler, at der følger direkte tale bagefter","Det adskiller to sætninger, der hører tæt sammen","Det viser, at første del er en ledsætning"],"a":"Det adskiller to sætninger, der hører tæt sammen","r":"Semikolon adskiller mere end et komma, men mindre end et punktum."},
{"l":8490,"g":8,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I en gammel tale opfordres folket til at 'ihukomme' de faldne. Hvad skal de gøre?","o":["hjælpe dem","begrave dem","tælle dem","mindes dem"],"a":"mindes dem","r":"'Ihukomme' betyder at huske på og mindes. 'Hu' er et gammelt ord for sind, så man skal altså have dem i sindet."},
{"l":8513,"g":8,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad er rigtigt? 'En person, der flytter til Danmark fra et andet land, er set herfra en ___.'","o":["immigrant","emigrant","imigrant","immigrand"],"a":"immigrant","r":"En immigrant er en, der rejser ind i et land. Ordet har i og dobbelt-m."},
{"l":8532,"g":8,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord bryder stilen i: 'Vi skal hermed meddele, at mødet er aflyst, hvilket er ret nederen.'?","o":["hermed","nederen","meddele","aflyst"],"a":"nederen","r":"Teksten er formel, men 'nederen' er slang. Et ord fra et helt andet register falder igennem."},
{"l":8556,"g":8,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad er særligt ved sproget i Steen Steensen Blichers 'E Bindstouw' fra 1842?","o":["Det er skrevet på latin","Det er skrevet på rimede sonetter","Det er skrevet på jysk dialekt","Det er skrevet som et skuespil"],"a":"Det er skrevet på jysk dialekt","r":"'E Bindstouw' betyder bindestuen. Blicher lod sine fortællinger og viser høres på jysk."},
{"l":8580,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Efter hvilket ord skal der komma, når sætningen slutter med et efterstillet led: 'Hun er en dygtig fodboldspiller den pige.'?","o":["dygtig","den","pige","fodboldspiller"],"a":"fodboldspiller","r":"'den pige' gentager grundleddet 'hun' og står løst efter sætningen. Derfor skilles det fra med komma."},
{"l":8606,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Efter hvilket ord er komma et krav: 'Alene det at han ringede viste at han fortrød.'?","o":["ringede","han","fortrød","Alene"],"a":"ringede","r":"Ledsætningen 'at han ringede' er indskudt og slutter efter 'ringede'. Andre kommaer her er valgfri startkommaer."},
{"l":8630,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken sætning har en ledsætning bygget efter skemaet: bindeord, grundled, sætningsadverbial, bøjet udsagnsord?","o":["Jeg tror, at Noah kan ikke komme.","Jeg tror, at Noah ikke kan komme.","Jeg tror, at kan Noah ikke komme.","Jeg tror, at ikke Noah kan komme."],"a":"Jeg tror, at Noah ikke kan komme.","r":"Efter 'at' kommer grundleddet 'Noah', så sætningsadverbialet 'ikke' og derefter det bøjede udsagnsord 'kan'. Det er ledsætningens faste rækkefølge i skemaet."},
{"l":8652,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken sætning passer bedst i en formel ansøgning om en praktikplads?","o":["Hej, jeg gider godt den der praktik hos jer.","Yo, giv mig lige den praktikplads hos jer.","Jeg vil gerne søge praktikpladsen hos jer.","Det kunne være fedt at hænge ud hos jer."],"a":"Jeg vil gerne søge praktikpladsen hos jer.","r":"En ansøgning kræver et høfligt og sagligt register. Ord som 'gider', 'yo' og 'hænge ud' hører til uformelt talesprog."},
{"l":8672,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder ordleddet 'krono-', som man finder i 'kronologi' og 'kronometer'?","o":["magt","farve","lyd","tid"],"a":"tid","r":"Det kommer af græsk 'chronos'. En kronologi er en ordning efter tid, og et kronometer er et præcist ur."},
{"l":8695,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilken roman af Hans Kirk fra 1928 regnes for den første danske kollektivroman?","o":["Fiskerne","Jørgen Stein","Hærværk","Det forsømte forår"],"a":"Fiskerne","r":"'Fiskerne' skildrer et helt fiskersamfund i stedet for én hovedperson. Romanen er kendt som en kollektivroman."},
{"l":8715,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Vælg rigtigt: 'Turen var hård, men ___ kom alle glade hjem.'","o":["ikke deste mindre","ikke desto mindre","ikke destomindre","ikke desto minder"],"a":"ikke desto mindre","r":"Udtrykket består af tre ord og betyder 'alligevel'."},
{"l":8736,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilket ord er forkert skrevet med stort: 'Professor Holm fra Aarhus Universitet talte om Renæssancen i Italien.'?","o":["Aarhus","Universitet","Renæssancen","Italien"],"a":"Renæssancen","r":"Historiske perioder skrives med lille, mens Aarhus Universitet er navnet på en institution."},
{"l":8755,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Vi siger, at tiden går. Men det er os, der går.' Hvad gør den anden sætning?","o":["Den forklarer, hvordan ure og kalendere virker","Den opfordrer læseren til at gå flere ture","Den forklarer, at tiden står stille om natten","Den minder os om, at det er os, der forsvinder"],"a":"Den minder os om, at det er os, der forsvinder","r":"En kendt talemåde bliver vendt om. Det er ikke tiden, der forsvinder, men os."},
{"l":8777,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad føler man, når man ser på nogen med 'medynk'?","o":["medlidenhed med en, der har det svært","misundelse over en, der har det godt","ærefrygt for en, der er meget klog","taknemmelighed mod en, der har hjulpet"],"a":"medlidenhed med en, der har det svært","r":"At ynke nogen er at have ondt af dem. Ordet kan have en lille smag af overlegenhed."},
{"l":8795,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvad er forskellen på 'en dansk lærer' og 'en dansklærer'?","o":["Den første underviser i dansk, den anden er fra Danmark.","Den første er fra Danmark, den anden underviser i dansk.","Der er ingen forskel, begge former betyder præcis det samme.","Den første er uddannet, den anden er ikke uddannet endnu."],"a":"Den første er fra Danmark, den anden underviser i dansk.","r":"Skrevet i to ord er 'dansk' et tillægsord, der siger noget om læreren. Som sammensat ord fortæller 'dansk' derimod, hvilket fag læreren har."},
{"l":8817,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"En tjener spørger én gæst: 'Vil De have kaffe?' Hvad viser 'De' om sproget?","o":["Det er uformelt og kammeratligt.","Det er slang fra storbyen.","Det er formelt og høfligt.","Det er lokal dialekt fra Jylland."],"a":"Det er formelt og høfligt.","r":"'De' er en høflig tiltale til en person, man ikke kender eller vil vise respekt. Det hører til et formelt register, hvor man ellers ville sige 'du'."},
{"l":8838,"g":9,"b":1,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'En skole er som en virksomhed: Eleverne er kunder, og kunden har altid ret. Derfor bør eleverne selv bestemme, hvad der står på skemaet.' Hvor halter sammenligningen mest?","o":["En virksomhed har som regel flere ansatte, end der er lærere på en skole","Skoler holder lang sommerferie, og det gør de fleste virksomheder ikke","Skoler ligger ikke samme steder i byen som virksomheder","En kunde ved, hvad han vil have, men en elev skal lære det ukendte"],"a":"En kunde ved, hvad han vil have, men en elev skal lære det ukendte","r":"Kunden ved, hvad han er kommet efter. En elev går i skole for at lære noget, hun endnu ikke kender, og kan derfor ikke selv vide, hvad der skal på skemaet."},
{"l":8861,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvor mange morfemer består 'venskabet' af?","o":["tre","to","fire","fem"],"a":"tre","r":"Ordet består af roden 'ven', afledningen '-skab' og bøjningsendelsen '-et'. Det har også tre stavelser, men det er et tilfælde."},
{"l":8882,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord er det modsatte af 'egoisme'?","o":["realisme","altruisme","skepticisme","materialisme"],"a":"altruisme","r":"Altruisme er uselvisk omsorg for andre og kommer af latin 'alter', der betyder den anden."},
{"l":8897,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Jeg husker, at jeg var glad den sommer. Det vil sige, jeg husker, at jeg har sagt det.' Hvad sår den anden sætning tvivl om?","o":["Om sommeren var varm nok","Hvem der lyttede den sommer","Om fortælleren husker rigtigt","Om fortælleren stadig er glad"],"a":"Om fortælleren husker rigtigt","r":"Fortælleren retter sig selv: Kun ordene kan huskes, ikke følelsen. Dermed bliver minderne usikre."},
{"l":8920,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Kommunen lover mere 'transparens' i sine beslutninger. Hvad lover den?","o":["hurtigere svar på alle breve","lavere skat til sine borgere","færre møder i byrådet","åbenhed, så alle kan følge med"],"a":"åbenhed, så alle kan følge med","r":"Transparent betyder gennemsigtig. Borgerne skal altså kunne se, hvordan beslutningerne bliver truffet."},
{"l":8940,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Find ordet: 'Journalisten lavede en ___ om livet på en fiskekutter.'","o":["reportage","raportage","reportasje","repportage"],"a":"reportage","r":"Ordet kommer fra fransk og ender på -age, selvom det lyder som -asje."},
{"l":8959,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Efter at skolen fik nye gardiner, steg karaktererne. Altså giver gardiner bedre karakterer.' Hvad er fejlen?","o":["At afsenderen angriber skolens lærere som personer","At to ting, der sker samtidig, gøres til årsag og virkning","At afsenderen kun stiller to yderligheder op mod hinanden","At begrundelsen blot gentager det, påstanden siger"],"a":"At to ting, der sker samtidig, gøres til årsag og virkning","r":"At noget sker samtidig, er ikke det samme, som at det ene skyldes det andet. Karaktererne kan være steget af helt andre grunde."},
{"l":8981,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvorfor skal en influencer tydeligt skrive, at et opslag er reklame?","o":["Fordi opslag uden ordet bliver vist til færre personer","Fordi influenceren ellers ikke kan få sine penge udbetalt","Fordi modtageren skal kunne se, at indholdet er betalt","Fordi ordet gør opslaget lettere at finde ved en søgning"],"a":"Fordi modtageren skal kunne se, at indholdet er betalt","r":"Reklame skal kunne genkendes som reklame. Ellers kan modtageren tro, at det er en ærlig, personlig anbefaling."},
{"l":9002,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Læs: 'Den nye formand var en katalysator for forandring i klubben.' Hvilken rolle spillede formanden?","o":["bremsede alle forandringer","så kun til fra sidelinjen","led under forandringen","satte fart i forandringen"],"a":"satte fart i forandringen","r":"I kemien fremskynder en katalysator en reaktion. I overført betydning er det en person eller begivenhed, der sætter noget i gang."},
{"l":9022,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Skolelederen skriver høfligt til fru Holm. Hvilket ord skal have stort: 'Vi har modtaget deres brev, og vi svarer hurtigt.'?","o":["deres","brev","modtaget","svarer"],"a":"deres","r":"Høfligt stedord til én person skrives med stort: Deres. Så kan det ikke forveksles med flertal."},
{"l":9045,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Vi læser både ældre og nyere ___ i dansk.'","o":["literatur","litteratur","litterratur","littaratur"],"a":"litteratur","r":"Ordet har dobbelt-t og ét r i midten."},
{"l":9062,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"En diplomat bliver erklæret 'persona non grata'. Hvad er vedkommende nu?","o":["en højt agtet person","en anonym person","en uønsket person","en person med to statsborgerskaber"],"a":"en uønsket person","r":"Latin 'gratus' betyder velkommen. En diplomat med den betegnelse skal forlade landet."},
{"l":9081,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken sætning har den rigtige form af 'al', 'alt' eller 'alle'?","o":["Vi drak alt mælken i går.","Vi drak alle mælken i går.","Vi drak ingen mælken i går.","Vi drak al mælken i går."],"a":"Vi drak al mælken i går.","r":"'Mælk' er fælleskøn og står i ental, så formen er 'al'. 'Alt' bruges ved intetkøn, og 'alle' bruges ved flertal."},
{"l":9102,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Læs: 'Tavs var hun, og blid var hendes stemme.' Hvad er særligt ved ordstillingen?","o":["inversion","epifor","metonymi","eufemisme"],"a":"inversion","r":"Ved inversion vendes den almindelige ordstilling om. 'Hun var tavs' bliver til 'tavs var hun' og får større vægt."},
{"l":9122,"g":9,"b":2,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad vil det sige at 'sluge kamelen'?","o":["at påstå noget, man ved er forkert","at acceptere noget, man egentlig er imod","at spise alt for meget på én gang","at tage hele æren for en andens arbejde"],"a":"at acceptere noget, man egentlig er imod","r":"En kamel er stor og svær at få ned. Man godtager noget ubehageligt, ofte for at nå et kompromis."},
{"l":9146,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvem gør H.C. Andersen især grin med i eventyret 'Klods-Hans'?","o":["Klods-Hans, der er for dum til at forstå noget","Prinsessen, der ikke vil have nogen af de mange fine bejlere","Brødrene, der kan alt udenad, men ikke kan svare for sig","Kongen, der lader alle bejlere komme på slottet"],"a":"Brødrene, der kan alt udenad, men ikke kan svare for sig","r":"De to brødre har lært en masse udenad, men bliver tavse foran prinsessen. Klods-Hans siger bare det, han kommer i tanke om, og vinder."},
{"l":9165,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Find det rigtige ord: 'Meteorologerne lavede en ___ for den kommende uge.'","o":["proknose","prognoce","pragnose","prognose"],"a":"prognose","r":"Ordet kommer fra græsk og indeholder gn. Det ender på -ose med s."},
{"l":9182,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad kaldes en kort, skarpsindig tanke, der er formuleret i en enkelt sætning?","o":["aforisme","novelle","fabel","krønike"],"a":"aforisme","r":"En aforisme er et koncentreret udsagn med en træffende pointe. De tre andre er længere, fortællende genrer."},
{"l":9204,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Hvilken sætning med 'ikke alene' og 'men' er rigtig?","o":["Hun vandt ikke, alene løbet men satte også rekord.","Hun vandt ikke alene løbet, men satte også rekord.","Hun vandt ikke alene løbet men, satte også rekord.","Hun vandt, ikke alene løbet men satte også rekord."],"a":"Hun vandt ikke alene løbet, men satte også rekord.","r":"Kommaet står foran 'men' og aldrig lige efter det."},
{"l":9224,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvad kaldes vokalskiftet i 'fod – fødder' og 'bog – bøger'?","o":["aflyd","stød","omlyd","rim"],"a":"omlyd","r":"Omlyd er et gammelt vokalskifte, der bl.a. ses i navneords flertal. Aflyd er det vokalskifte, der ses i stærke udsagnsord."},
{"l":9242,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Ingen skrev noget mindeord, da skolen i Vesterby lukkede. Nøglerne blev lagt i en skuffe på rådhuset, hvor der allerede lå nøgler fra tre andre landsbyskoler.' Hvad vil den sidste oplysning sige?","o":["At rådhuset har brug for flere skuffer til nøgler","At de tre andre skoler snart åbner igen til sommer","At nøglerne bliver opbevaret forkert på rådhuset","At den ene landsbyskole efter den anden lukker"],"a":"At den ene landsbyskole efter den anden lukker","r":"I skuffen ligger der allerede nøgler fra tre andre skoler. Så skolerne lukker én efter én, og ingen siger noget om det."},
{"l":9265,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad kendetegner en 'obsternasig' teenager?","o":["trodsig og genstridig","stille og forsigtig","klog og hurtig","svag og sygelig"],"a":"trodsig og genstridig","r":"Obsternasig betyder oprørsk og vanskelig at styre. Ordet bruges tit om børn og unge, der sætter sig imod."},
{"l":9285,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad skal der stå? 'Min søster har et voldsomt ___ og bliver hurtigt vred.'","o":["tempramænt","temperament","temparament","tempermant"],"a":"temperament","r":"Ordet har e i midten og ender på -ment. Husk alle fire stavelser: tem-pe-ra-ment."},
{"l":9302,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Hun sagde, at hun ikke var sur. Hun sagde det helt roligt, mens hun stillede alle hans bøger ud på trappen i alfabetisk orden.' Hvad viser den alfabetiske orden?","o":["At hun passer godt på hans bøger, selv nu","At hun selv vil have bøgerne, når han er væk","At hun er meget vred, men holder hovedet koldt","At hun faktisk ikke er sur, som hun siger"],"a":"At hun er meget vred, men holder hovedet koldt","r":"Hun stiller hans bøger på trappen, så hun er ikke så rolig, som hun siger. Men man sætter ikke bøger i alfabetisk orden i et raserianfald. Hun har tænkt sig om, og det gør det næsten værre."},
{"l":9326,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Det år, vi boede over bageriet, sov jeg bedre end nogensinde. Nu bor jeg i et hus med udsigt og stilhed, og når nogen spørger, siger jeg, at det er dejligt. Forleden duftede et supermarked af kardemomme, og jeg blev stående længe ved brødet.' Hvad lader teksten læseren forstå uden at sige det?","o":["At fortælleren har fortrudt flytningen og er på vej tilbage","At fortælleren aldrig har kunnet sove i et hus med stilhed","At supermarkedets brød ikke kan måle sig med det fra bageriet","At fortælleren savner noget, som det fine hus ikke kan give"],"a":"At fortælleren savner noget, som det fine hus ikke kan give","r":"Duften holder fortælleren fast, fordi den vækker noget, huset mangler. Brødet er kun anledningen, og intet tyder på, at fortælleren er på vej væk."},
{"l":9345,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket led er 'en helt' i: 'Hele byen kaldte brandmanden en helt.'","o":["omsagnsled til genstandsleddet","omsagnsled til grundleddet","hensynsled","forholdsordsled"],"a":"omsagnsled til genstandsleddet","r":"'En helt' siger noget om 'brandmanden', som er genstandsled. Derfor er det et omsagnsled til genstandsleddet og ikke et nyt genstandsled."},
{"l":9367,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilken af omskrivningerne gør 'tid' til det sidste og vigtigste i sætningen, uden at meningen ændres: 'Jeg mangler tid.'","o":["Mangler jeg mon tid?","Det, jeg mangler, er tid.","Tid er, hvad jeg har.","Jeg har rigelig tid."],"a":"Det, jeg mangler, er tid.","r":"Omskrivningen med 'Det, jeg mangler, er …' skaber spænding hen mod det sidste ord. Meningen er den samme, men fokus ligger nu på 'tid'."},
{"l":9388,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad kendetegner poetisk realisme i dansk litteratur i 1800-tallet?","o":["Uhygge, spøgelser og ødelagte borge","Sult, fabrikker og strejker i storbyen","Hygge, idyl og det borgerlige hverdagsliv","Eksperimenter med fragmenter og tomme sider"],"a":"Hygge, idyl og det borgerlige hverdagsliv","r":"Efter den vilde romantik vendte forfatterne sig mod hverdagen, men de så den stadig i et poetisk skær."},
{"l":9410,"g":9,"b":3,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilken dansk tænker udgav 'Enten – Eller' i 1843?","o":["N.F.S. Grundtvig","Georg Brandes","Henrik Steffens","Søren Kierkegaard"],"a":"Søren Kierkegaard","r":"Søren Kierkegaard skrev 'Enten – Eller' om valget mellem forskellige måder at leve på."},
{"l":9433,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Et diagram viser, at der i år bygges 400 nye boliger i byen. Forvaltningen skriver: Der bygges nok til børnefamilierne. I søjlens fodnote står der, at 390 af boligerne er etværelses.' Hvad afslører fodnoten?","o":["At de fleste boliger er for små til familier","At der bygges flere boliger, end der står i diagrammet","At børnefamilierne foretrækker at bo i små lejligheder","At diagrammet slet ikke viser de nye boliger i byen"],"a":"At de fleste boliger er for små til familier","r":"Der bygges 400 boliger, men få familier kan bo i ét værelse. Så passer det ikke, at der bygges nok til dem."},
{"l":9454,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad betyder vanitas-motivet i litteratur og kunst?","o":["At sandheden altid kommer frem","At alt jordisk er forgængeligt","At kærlighed overvinder alt","At fornuften vil sejre til sidst"],"a":"At alt jordisk er forgængeligt","r":"Vanitas er latin for tomhed. Motivet minder os om, at rigdom, skønhed og liv ikke varer ved."},
{"l":9475,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Et debatindlæg bliver kaldt 'perfidt'. Hvad beskylder man det for?","o":["at være åbent og ærligt","at være klodset og dumt","at være lumsk og ondsindet","at være kort og kontant"],"a":"at være lumsk og ondsindet","r":"Perfid kommer af latin 'perfidus', der betyder troløs. Et perfidt angreb rammer på en lumsk og uredelig måde."},
{"l":9492,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Brochuren kalder øen for solskinsøen. Ved hver eneste hoveddør står der gummistøvler. Butikken på havnen sælger ikke solcreme, men den har tre hylder med paraplyer. I hotellets gæstebog har en familie skrevet: Dejlig uge, vi så solen i tirsdags.' Hvad kan man regne ud om vejret på øen?","o":["Solen skinner så meget, at butikken ikke kan få solcreme nok.","Det regner kun om tirsdagen, ellers er der sol hele ugen.","Det er varmt og tørt, præcis som der står i brochuren.","Det regner meget mere, end brochuren siger."],"a":"Det regner meget mere, end brochuren siger.","r":"Gummistøvler og tre hylder med paraplyer viser, at folk på øen er vant til regn. Familien skriver om solen, som om det var noget særligt at se den."},
{"l":9512,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad kaldes en styreform, hvor de rigeste har magten?","o":["plutokrati","teokrati","meritokrati","monarki"],"a":"plutokrati","r":"Græsk 'plutos' betyder rigdom. I et teokrati regerer man derimod i guddommens navn."},
{"l":9535,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad sker der, når et land 'devaluerer' sin valuta?","o":["Den får højere værdi over for andre valutaer","Den får lavere værdi over for andre valutaer","Den bliver erstattet af guld eller sølv","Den bliver afskaffet i hele landet"],"a":"Den får lavere værdi over for andre valutaer","r":"De- betyder ned, så værdien sættes ned. Det gør landets varer billigere at købe for udlandet."},
{"l":9555,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad står der rigtigt? 'Mayaerne var en højt udviklet ___.'","o":["sivilisation","civillisation","civilisation","civilasation"],"a":"civilisation","r":"Ordet begynder med c, har ét l og slutter på -sation."},
{"l":9576,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvad kaldes vokalskiftet i 'synge – sang – sunget'?","o":["omlyd","stød","tryk","aflyd"],"a":"aflyd","r":"Aflyd er det vokalskifte, der ses i stærke udsagnsord, når tiden skifter. Det er ældgammelt og går tilbage til det indoeuropæiske ursprog."},
{"l":9597,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvad undersøger man, når man ser på en teksts kommunikationssituation?","o":["Hvem der siger hvad til hvem og med hvilket formål","Hvad teksten handler om fra start til slut","Hvilke sproglige billeder teksten bruger","Hvilken genre og hvilken periode teksten hører til"],"a":"Hvem der siger hvad til hvem og med hvilket formål","r":"Kommunikationssituationen handler om afsender, modtager, budskab og hensigt, altså rammen om teksten."},
{"l":9617,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"John Locke mente, at barnets sind fra fødslen er en 'tabula rasa'. Hvad betyder det?","o":["et færdigt system af ideer","et ubeskrevet blad","en arv fra forældrene","et gemmested for gamle minder"],"a":"et ubeskrevet blad","r":"Latin 'tabula rasa' betyder en afskrabet tavle. Ifølge Locke kommer alt indhold først med erfaringen."},
{"l":9640,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"I fysikken bruges ordet 'entropi'. Hvad er det et mål for?","o":["mængden af lys i et lukket rum","styrken af en magnet","graden af uorden i et system","vægten af et atom"],"a":"graden af uorden i et system","r":"Entropien i et isoleret system kan ikke falde. Derfor blander mælk og kaffe sig af sig selv, men de skilles aldrig igen af sig selv."},
{"l":9660,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Landene omkring ___ har varmt klima hele året.'","o":["ekvator","ækvatur","ækvater","ækvator"],"a":"ækvator","r":"Ordet begynder med æ og slutter på -tor."},
{"l":9677,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad er en 'epigon' i kunstens verden?","o":["en efterligner uden egen fornyelse","en kunstner, der skaber noget nyt","en samler af meget dyre værker","en anmelder ved en stor avis"],"a":"en efterligner uden egen fornyelse","r":"Græsk 'epigonos' betyder efterkommer. Ordet bruges kritisk om en, der blot gentager de stores stil."},
{"l":9698,"g":9,"b":4,"role":"deep_challenge","insight":"perspective_shift","k":"t","variant":"authored","q":"Det er Noah, der taler, og han siger, at Emma er sød. Hvilken sætning viser det?","o":["Emma sagde, Noah er sød.","Emma, sagde Noah, er sød.","Emma sagde Noah, er sød.","Emma, sagde Noah er sød."],"a":"Emma, sagde Noah, er sød.","r":"'sagde Noah' er skudt ind, og kommaerne på begge sider viser, at det er Noah, der taler."},
{"l":9720,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad står der rigtigt? 'Forskerne gjorde et ___ fund i mosen.'","o":["opsigtsvækende","opsigtvækkende","opsigtsvækkende","opsigtsvækkene"],"a":"opsigtsvækkende","r":"Ordet har fuge-s efter 'opsigt', dobbelt-k og -ende med d."},
{"l":9741,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"I hvilken af sætningerne kan man udelade 'som'?","o":["Cyklen, som stod i gården, var rusten.","Læreren, som underviste os, var sød.","Manden, som boede her, var sømand.","Bogen, som jeg læste, var spændende."],"a":"Bogen, som jeg læste, var spændende.","r":"'Som' kan kun udelades, når det ikke er grundled i ledsætningen. I facit er 'jeg' grundled, mens 'som' i de andre sætninger selv er grundled."},
{"l":9762,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"f","variant":"authored","q":"Hvilken historisk begivenhed prægede især Heretica-digternes kriseoplevelse?","o":["Anden Verdenskrig","Krigen i 1864","Den franske revolution","Reformationen"],"a":"Anden Verdenskrig","r":"Heretica startede lige efter besættelsen. Krigen havde rystet troen på fornuft og fremskridt."},
{"l":9782,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad beskylder man en person for, hvis man kalder vedkommende 'bornert'?","o":["at være født med særlige talenter","at være indskrænket og snæversynet","at være doven og uansvarlig","at være sky og usikker"],"a":"at være indskrænket og snæversynet","r":"Ordet kommer af fransk 'borner', at begrænse. Det har intet med det engelske 'born' at gøre."},
{"l":9802,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Tilflyttere er glade for den nye færgerute, mens fastboende klager over støj. Turistchefen kalder fremtiden lys. Fiskerne siger intet, for de har ikke været inviteret til mødet.' Hvad er det, sidste sætning peger på?","o":["At fiskerne ikke interesserer sig for havnens fremtid","At fiskerne er enige med turistchefen i hans lyse vurdering","At man ikke har hørt fiskerne, fordi ingen har spurgt dem","At mødet er blevet aflyst, fordi for få meldte sig"],"a":"At man ikke har hørt fiskerne, fordi ingen har spurgt dem","r":"Fiskerne siger ikke noget, men det er ikke, fordi de er enige. De er bare ikke blevet inviteret."},
{"l":9826,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Ja, jeg er musikanmelder og kan ikke selv spille et instrument. Det får jeg ofte at vide i læserbreve. Men det er netop derfor, jeg hører det, publikum hører, og ikke det, der står i noderne.' Hvordan svarer skribenten på kritikken?","o":["Skribenten siger, at kritikken slet ikke passer","Skribenten giver kritikerne ret, men er ligeglad med det","Skribenten vender kritikken mod de musikere, der kun tænker på noder","Skribenten giver kritikerne ret og gør det til en fordel"],"a":"Skribenten giver kritikerne ret og gør det til en fordel","r":"Skribenten siger ja og gør manglen til en fordel. Det er mere end at kalde den ligegyldig, for 'netop derfor' viser, at den bruges aktivt som styrke."},
{"l":9842,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad kaldes en tænkemåde, hvor modsætninger mødes og føres videre til en højere enhed?","o":["dialektik","didaktik","statistik","logistik"],"a":"dialektik","r":"Ordet kommer af græsk for samtale. Tese og antitese støder sammen og fører til en syntese."},
{"l":9870,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Hvad er rigtigt? 'En ___ er en læge med speciale i psykiske sygdomme.'","o":["psykiatter","psykiater","psykiatær","sykiater"],"a":"psykiater","r":"Ordet begynder med ps og har ét t. Det ender på -er."},
{"l":9885,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"s","variant":"authored","q":"Vælg stavemåden: 'Efter skaden fik hun øvelser af en ___.'","o":["fysioterrapeut","fysioterapet","fysioterapeut","fysoterapeut"],"a":"fysioterapeut","r":"Ordet består af 'fysio' og 'terapeut'. Det har ét r og eu sidst i ordet."},
{"l":9906,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Udsagnsordet 'fælde' betyder 'få til at falde'. Hvilket ordpar har samme forhold?","o":["købe – sælge","spise – drikke","gå – løbe","synke – sænke"],"a":"synke – sænke","r":"'Sænke' betyder at få noget til at synke. Sådanne udsagnsord kaldes kausative, fordi de udtrykker, at man forårsager noget."},
{"l":9928,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Latin 'pater', 'piscis' og 'pes' svarer til dansk 'fader', 'fisk' og 'fod'. Hvad viser det?","o":["Germansk f svarer til latinsk p.","Dansk lånte ordene fra latin.","Latin lånte ordene fra dansk.","Ordene er tilfældigt ens."],"a":"Germansk f svarer til latinsk p.","r":"Ordene stammer fra et fælles ursprog, og indoeuropæisk p blev til f i de germanske sprog. Lydloven kaldes Grimms lov."},
{"l":9947,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder det, at et kunstværk er 'sui generis'?","o":["Det er bestilt af en rig og fornem kunde","Det er enestående og i sin egen klasse","Det er lavet af flere kunstnere i fællesskab","Det er en tro kopi af et ældre værk"],"a":"Det er enestående og i sin egen klasse","r":"Latin 'sui generis' betyder 'af sin egen art'. Værket passer altså ikke ind i nogen kendt kategori."},
{"l":9970,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad er 'arbitrage' på de finansielle markeder?","o":["at låne penge til lav rente af staten","at forsikre sig mod dårligt vejr i høsten","at tjene på prisforskelle mellem markeder","at holde fast i sine aktier i mange år"],"a":"at tjene på prisforskelle mellem markeder","r":"Man køber noget, hvor det er billigt, og sælger det samtidig, hvor det er dyrt. Forskellen er gevinsten."},
{"l":9992,"g":9,"b":5,"role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"En historiker afviser en forklaring som 'post hoc, ergo propter hoc'. Hvilken fejl peger historikeren på?","o":["at man tror, at noget, der er gammelt, altid er bedst","at man tror, at flertallet altid må have ret","at man tror, at to modsætninger begge er forkerte","at man tror, at det, der sker efter noget, skyldes det"],"a":"at man tror, at det, der sker efter noget, skyldes det","r":"Latin for 'efter dette, altså på grund af dette'. At noget kommer bagefter, beviser ikke, at det er forårsaget af det første."}
]$$::jsonb) AS e
JOIN (VALUES
  ('s', 'stavning', 'recall', 'factual', 'surface_association'),
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('t', 'tegnsætning', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'comprehension', 'conceptual', 'surface_association'),
  ('f', 'litteratur', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
